package com.gen3d.remote.tests;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import android.webkit.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.json.*;
public class AndroidWorkflowTest extends Instrumentation{
 Activity activity;WebView web;String desktop="http://10.0.2.2:9878";
 public void onCreate(Bundle b){super.onCreate(b);if(b!=null)desktop=b.getString("desktop",desktop);start();}
 void step(String s){Bundle b=new Bundle();b.putString("step",s);sendStatus(1,b);}
 View find(View v,Class<?> c,String text){if(c.isInstance(v)&&(text==null||(v instanceof TextView&&((TextView)v).getText().toString().equalsIgnoreCase(text))))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View f=find(g.getChildAt(i),c,text);if(f!=null)return f;}}return null;}
 String eval(String s)throws Exception{CountDownLatch l=new CountDownLatch(1);AtomicReference<String> r=new AtomicReference<>("");runOnMainSync(()->web.evaluateJavascript(s,value->{r.set(value);l.countDown();}));if(!l.await(30,TimeUnit.SECONDS)){AtomicReference<String> info=new AtomicReference<>();runOnMainSync(()->info.set(web.getUrl()+" progress="+web.getProgress()));throw new Exception("WebView callback timed out: "+info.get());}Object o=new JSONTokener(r.get()).nextValue();return o==JSONObject.NULL?"":String.valueOf(o);}
 void waitFor(String s)throws Exception{long end=SystemClock.elapsedRealtime()+60000;while(SystemClock.elapsedRealtime()<end){if("true".equals(eval("Boolean("+s+")")))return;Thread.sleep(300);}throw new Exception("Failed condition: "+s);}
 public void onStart(){Bundle b=new Bundle();try{step("launch");activity=startActivitySync(new Intent().setClassName("com.gen3d.remote","com.gen3d.remote.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));runOnMainSync(()->web=(WebView)find(activity.getWindow().getDecorView(),WebView.class,null));if(web==null)throw new Exception("No native WebView");for(int i=0;i<120;i++){AtomicInteger progress=new AtomicInteger();runOnMainSync(()->progress.set(web.getProgress()));if(progress.get()==100)break;Thread.sleep(500);}step("page ready");waitFor("document.getElementById('localBibleSearch')");step("offline KJV");eval("document.getElementById('localBibleQuery').value='John 3:16';document.getElementById('localBibleSearch').click()");waitFor("document.getElementById('localBibleResults').textContent.includes('For God so loved the world')");step("desktop connection");runOnMainSync(()->{View v=activity.getWindow().getDecorView();((EditText)find(v,EditText.class,null)).setText(desktop);find(v,Button.class,"Open desktop remote").performClick();});waitFor("document.getElementById('pin')&&location.protocol!=='file:'");eval("document.getElementById('pin').value='1234';document.getElementById('connect').click()");waitFor("document.getElementById('status').textContent.includes('Connected to desktop')");waitFor("document.getElementById('library').textContent.includes('Android test hymn')");step("authenticated command");eval("document.querySelector('[data-command=next]').click();document.getElementById('saveOfflineCopy').click()");waitFor("document.getElementById('status').textContent.includes('Offline copy saved')");step("native snapshot transfer");runOnMainSync(()->find(activity.getWindow().getDecorView(),Button.class,"Offline library & KJV Bible").performClick());waitFor("location.protocol==='file:'&&document.getElementById('openOfflineCopy')");eval("document.getElementById('openOfflineCopy').click()");waitFor("document.getElementById('status').textContent.includes('Offline copy')&&document.getElementById('library').textContent.includes('Android test hymn')");waitFor("Array.from(document.querySelectorAll('[data-command]')).every(button=>button.disabled)");eval("document.getElementById('localBibleQuery').value='Psalm 23:1';document.getElementById('localBibleSearch').click()");waitFor("document.getElementById('localBibleResults').textContent.includes('The LORD is my shepherd')");b.putString("gen3d_result","PASS");b.putString("checks","release APK, offline KJV, native address connection, PIN auth, command send, offline snapshot transfer, disabled offline controls");finish(Activity.RESULT_OK,b);}catch(Throwable e){b.putString("gen3d_result","FAIL");b.putString("failure",e.toString());finish(Activity.RESULT_CANCELED,b);}}
}
